// удалить i-й за O(1), если порядок не важен
static void RemoveAtSwap<T>(List<T> list, int i) {
    int last = list.Count - 1;
    list[i] = list[last];   // последний — на место удаляемого
    list.RemoveAt(last);    // удаление с конца ничего не сдвигает
}

