// обход в ширину по сетке: очередь клеток
var queue = new Queue<(int x, int y)>();
queue.Enqueue((sx, sy));
visited[sx, sy] = true;
while (queue.Count > 0) {
    var (x, y) = queue.Dequeue();           // O(1): head идёт по кругу
    foreach (var (dx, dy) in Dirs) {
        int nx = x + dx, ny = y + dy;
        if (Passable(nx, ny) && !visited[nx, ny]) {
            visited[nx, ny] = true;
            queue.Enqueue((nx, ny));         // O(1) амортизированно
        }
    }
}

