// .NET 6+: ленивое удаление вместо decrease-key
var pq = new PriorityQueue<int, int>();   // элемент — вершина, приоритет — расстояние
pq.Enqueue(start, 0);
while (pq.TryDequeue(out int v, out int d)) {
    if (d > dist[v]) continue;            // устаревшая копия — пропускаем
    foreach (var (to, w) in graph[v])
        if (d + w < dist[to]) {
            dist[to] = d + w;
            pq.Enqueue(to, d + w);        // новая копия; старая останется в куче
        }
}
// max-куча: new PriorityQueue<int, int>(Comparer<int>.Create((a, b) => b.CompareTo(a)))

